using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Serialization;
using UnityEngine.XR.Interaction.Toolkit;
using UnityEngine.XR.Interaction.Toolkit.Interactables;

namespace FurBrains
{
    /// <summary>
    /// Top-level behaviour of a placed FurBrain: plays an animation when it's summoned, tapped or fed, idles in
    /// between, and slowly turns to face the player.
    /// </summary>
    /// <remarks>
    /// <b>Choosing animations:</b> drag clips into the Idle / Summon / Tap / Feed Animation fields in the Inspector.
    /// The Animator Controller (generated by FurBrainsPetBuilder) has one state per action, each holding an empty
    /// placeholder "slot" clip. In Awake we wrap that controller in an <c>AnimatorOverrideController</c>, which says
    /// "wherever the controller would play clip X, play clip Y instead", and fill each slot with the clip chosen here.
    /// The state machine itself (transitions, triggers) never changes; only which clips it plays. The swap is done
    /// once, before anything plays, because changing overrides while the Animator is running restarts it.
    ///
    /// <b>Taps:</b> uses the XR Interaction Toolkit interactable on the same object (an XRSimpleInteractable, which can
    /// be selected but never moves the object). XRI doesn't have a separate "tap" event: touching the FurBrain
    /// <i>selects</i> it and lifting the finger <i>deselects</i> it, so we treat a short select as a tap.
    /// </remarks>
    [RequireComponent(typeof(XRBaseInteractable))]
    public class FurBrainPet : MonoBehaviour
    {
        // Animator trigger parameters, one per action (the pet builder creates matching states).
        /// <summary>Trigger for the summon animation.</summary>
        public const string SummonTrigger = "Summon";
        /// <summary>Trigger for the tap animation.</summary>
        public const string TapTrigger = "Tap";
        /// <summary>Trigger for the feed animation.</summary>
        public const string FeedTrigger = "Feed";

        // Names of the placeholder clips in the generated controller, which the clips below replace.
        /// <summary>Placeholder clip name for the idle state.</summary>
        public const string IdleSlot = "Slot_Idle";
        /// <summary>Placeholder clip name for the summon state.</summary>
        public const string SummonSlot = "Slot_Summon";
        /// <summary>Placeholder clip name for the tap state.</summary>
        public const string TapSlot = "Slot_Tap";
        /// <summary>Placeholder clip name for the feed state.</summary>
        public const string FeedSlot = "Slot_Feed";

        [Header("Animations")]
        [SerializeField]
        [Tooltip("Loops while nothing else is playing. Tick Loop Time on the clip (Idle/ clips loop automatically).")]
        AnimationClip m_IdleAnimation;

        [SerializeField]
        [Tooltip("Plays once when the FurBrain is summoned.")]
        AnimationClip m_SummonAnimation;

        [SerializeField]
        [Tooltip("Plays once when the player taps the FurBrain.")]
        AnimationClip m_TapAnimation;

        [SerializeField]
        [Tooltip("Plays once when the FurBrain is fed.")]
        AnimationClip m_FeedAnimation;

        [Header("Expressions")]
        [SerializeField]
        [Tooltip("Blend shapes shown while the summon animation plays (see FurBrainMood for Ziara's shape names).")]
        string[] m_SummonExpression = { "Empowered" };

        [SerializeField]
        [Tooltip("Blend shapes shown while the tap animation plays.")]
        string[] m_TapExpression = { "Surprised" };

        [SerializeField]
        [Tooltip("Blend shapes shown while the feed animation plays.")]
        string[] m_FeedExpression = { "Empowered" };

        [SerializeField]
        [Tooltip("Hold the expression for as long as the action's animation plays. Off, or for an action without " +
                 "an animation, the expression lasts Expression Duration.")]
        bool m_MatchExpressionToAnimation = true;

        [SerializeField, FormerlySerializedAs("m_HappyFaceDuration")]
        [Tooltip("How long an expression lasts, in seconds, when it isn't matched to an animation.")]
        float m_ExpressionDuration = 2.5f;

        [Header("Behaviour")]
        [SerializeField]
        [Tooltip("Animator on the character model. Found in children automatically if left empty.")]
        Animator m_Animator;

        [SerializeField]
        [Tooltip("Face controller on the character model. Found in children automatically if left empty.")]
        FurBrainFace m_Face;

        // FormerlySerializedAs keeps the value saved under the field's old name when it was renamed.
        [SerializeField, FormerlySerializedAs("m_WaveOnSpawn")]
        [Tooltip("Play the summon animation as soon as the FurBrain is placed.")]
        bool m_PlaySummonAnimation = true;

        [SerializeField]
        [Tooltip("Longest touch, in seconds, that still counts as a tap rather than a drag.")]
        float m_MaxTapDuration = 0.35f;

        [SerializeField]
        [Tooltip("Slowly turn to face the player (the AR camera).")]
        bool m_FacePlayer = true;

        [SerializeField]
        [Tooltip("Turning speed in degrees per second.")]
        float m_TurnSpeed = 45f;

        [SerializeField]
        [Tooltip("Start turning once the player is more than this many degrees off to the side.")]
        float m_StartTurnAngle = 20f;

        [SerializeField]
        [Tooltip("Stop turning once facing the player within this many degrees.")]
        float m_StopTurnAngle = 2f;

        XRBaseInteractable m_Interactable;
        FurBrainMood m_Mood;
        MinigameRunner m_Runner;
        Camera m_Camera;
        float m_SelectStartTime;
        float m_ClearFaceTime = -1f;
        string[] m_FaceShapesToClear;
        bool m_Turning;

        /// <summary>Animator on the character model.</summary>
        public Animator animator
        {
            get => m_Animator;
            set => m_Animator = value;
        }

        /// <summary>Looping idle clip.</summary>
        public AnimationClip idleAnimation { get => m_IdleAnimation; set => m_IdleAnimation = value; }

        /// <summary>Clip played when summoned.</summary>
        public AnimationClip summonAnimation { get => m_SummonAnimation; set => m_SummonAnimation = value; }

        /// <summary>Clip played when tapped.</summary>
        public AnimationClip tapAnimation { get => m_TapAnimation; set => m_TapAnimation = value; }

        /// <summary>Clip played when fed.</summary>
        public AnimationClip feedAnimation { get => m_FeedAnimation; set => m_FeedAnimation = value; }

        void Awake()
        {
            m_Interactable = GetComponent<XRBaseInteractable>();
            if (m_Animator == null)
                m_Animator = GetComponentInChildren<Animator>();
            if (m_Face == null)
                m_Face = GetComponentInChildren<FurBrainFace>();
            m_Mood = GetComponent<FurBrainMood>();
            // The pet is spawned at runtime, so it can't have a scene reference dragged in; look the runner up instead.
            m_Runner = FindAnyObjectByType<MinigameRunner>();

            ApplyAnimationClips();
        }

        /// <summary>
        /// Replaces the controller's placeholder slot clips with the clips chosen in the Inspector.
        /// </summary>
        void ApplyAnimationClips()
        {
            if (m_Animator == null || m_Animator.runtimeAnimatorController == null)
                return;

            // If the Animator already has an override controller, build on the controller underneath it.
            var baseController = m_Animator.runtimeAnimatorController is AnimatorOverrideController existing
                ? existing.runtimeAnimatorController
                : m_Animator.runtimeAnimatorController;
            var overrideController = new AnimatorOverrideController(baseController) { name = $"{name} Animations" };

            // List of (original clip, replacement) pairs, like std::vector<std::pair<Clip*, Clip*>>.
            var overrides = new List<KeyValuePair<AnimationClip, AnimationClip>>();
            overrideController.GetOverrides(overrides);
            for (var i = 0; i < overrides.Count; i++)
            {
                var replacement = overrides[i].Key.name switch
                {
                    IdleSlot => m_IdleAnimation,
                    SummonSlot => m_SummonAnimation,
                    TapSlot => m_TapAnimation,
                    FeedSlot => m_FeedAnimation,
                    _ => null,
                };
                overrides[i] = new KeyValuePair<AnimationClip, AnimationClip>(overrides[i].Key, replacement);
            }
            overrideController.ApplyOverrides(overrides);
            m_Animator.runtimeAnimatorController = overrideController;
        }

        void OnEnable()
        {
            m_Interactable.selectEntered.AddListener(OnSelectEntered);
            m_Interactable.selectExited.AddListener(OnSelectExited);
        }

        void OnDisable()
        {
            m_Interactable.selectEntered.RemoveListener(OnSelectEntered);
            m_Interactable.selectExited.RemoveListener(OnSelectExited);
        }

        void Start()
        {
            if (m_PlaySummonAnimation)
                PlayAction(SummonTrigger, m_SummonAnimation, m_SummonExpression);
        }

        void Update()
        {
            // Without a FurBrainMood we turn the reaction expression off ourselves (with one, the mood does it).
            if (m_ClearFaceTime >= 0f && Time.time >= m_ClearFaceTime)
            {
                m_ClearFaceTime = -1f;
                if (m_Face != null && m_FaceShapesToClear != null)
                    foreach (var shape in m_FaceShapesToClear)
                        m_Face.SetShape(shape, 0f);
            }

            if (m_FacePlayer)
                TurnTowardPlayer();
        }

        /// <summary>
        /// Turns around the FurBrain's own up axis (the surface normal it was placed on) toward the camera.
        /// </summary>
        /// <remarks>
        /// Uses two thresholds (hysteresis) so it doesn't twitch with every small head movement: it only starts turning
        /// once the player is clearly off to the side, then keeps turning until it's facing them almost exactly.
        /// </remarks>
        void TurnTowardPlayer()
        {
            if (m_Camera == null)
                m_Camera = Camera.main;
            if (m_Camera == null)
                return;

            var up = transform.up;
            var toPlayer = Vector3.ProjectOnPlane(m_Camera.transform.position - transform.position, up);
            if (toPlayer.sqrMagnitude < 1e-6f)
                return; // camera directly above: no meaningful direction

            var angle = Vector3.Angle(transform.forward, toPlayer);
            if (!m_Turning && angle > m_StartTurnAngle)
                m_Turning = true;
            else if (m_Turning && angle < m_StopTurnAngle)
                m_Turning = false;

            if (m_Turning)
            {
                var target = Quaternion.LookRotation(toPlayer, up);
                // RotateTowards moves at most this many degrees this frame: a constant speed, independent of frame rate.
                transform.rotation = Quaternion.RotateTowards(transform.rotation, target, m_TurnSpeed * Time.deltaTime);
            }
        }

        /// <summary>React to being fed: feed animation plus the feed expression.</summary>
        public void Eat() => PlayAction(FeedTrigger, m_FeedAnimation, m_FeedExpression);

        /// <summary>
        /// Cheer (e.g. after a minigame): replays the summon animation and expression. A dedicated celebrate slot can
        /// replace this later.
        /// </summary>
        public void Celebrate() => PlayAction(SummonTrigger, m_SummonAnimation, m_SummonExpression);

        /// <summary>React to a tap: tap animation plus the tap expression.</summary>
        public void OnTapped() => PlayAction(TapTrigger, m_TapAnimation, m_TapExpression);

        void PlayAction(string trigger, AnimationClip clip, string[] expression)
        {
            // An empty Animation field means "no animation for this action" (the face still reacts).
            if (m_Animator != null && clip != null)
                m_Animator.SetTrigger(trigger);

            // clip.length is the clip's duration in seconds. The Animator starts heading back to Idle at 95% of it,
            // so the expression ends as the body settles. (Animator speed is 1, so clip time = real time.)
            var seconds = m_MatchExpressionToAnimation && clip != null ? clip.length : m_ExpressionDuration;
            if (expression == null || expression.Length == 0)
                return; // no expression for this action: the hunger mood stays

            // FurBrainMood (if present) owns the face, so ask it; it returns to the hunger mood afterwards.
            if (m_Mood != null)
            {
                m_Mood.React(seconds, expression);
            }
            else if (m_Face != null)
            {
                foreach (var shape in expression)
                    m_Face.SetShape(shape, 1f);
                m_FaceShapesToClear = expression;
                m_ClearFaceTime = Time.time + seconds;
            }
        }

        void OnSelectEntered(SelectEnterEventArgs args)
        {
            m_SelectStartTime = Time.time;
        }

        void OnSelectExited(SelectExitEventArgs args)
        {
            // During a minigame, the player's taps are for the game (hitting the ball, popping bubbles, picking a cup),
            // so they don't count as tapping the FurBrain. Games can still call OnTapped() themselves for a reaction.
            if (m_Runner != null && m_Runner.isPlaying)
                return;
            if (!args.isCanceled && Time.time - m_SelectStartTime <= m_MaxTapDuration)
                OnTapped();
        }
    }
}
